import app from 'flarum/forum/app';
import { checkout } from '../../common/api';
/**
 * Buy a price: sign in first if needed, ask the terms and the provider only
 * when there is something to ask, then hand over to the provider's page.
 */
export function buy(product, price, meta, options = {}) {
  if (!app.session.user) {
    // 🚨 Flarum 2 modals are lazy chunks: a static import is undefined.
    app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'));
    return null;
  }
  if (meta.termsUrl || meta.providers.length > 1) {
    app.modal.show(() => import(/* webpackChunkName: 'forum/components/CheckoutModal', webpackMode: 'lazy-once' */ './CheckoutModal'), {
      product,
      price,
      meta,
      options
    });
    return null;
  }
  return go(price, meta.providers[0]?.key || 'paypal', options);
}
export function go(price, provider, options = {}) {
  return checkout(price.id, provider, options).then(({
    data
  }) => {
    window.location.href = data.url;
  });
}
flarum.reg.add('ernestdefoe-kiosk', 'forum/components/buy', { buy: buy,go: go, });flarum.reg.addChunkModule('ernestdefoe-kiosk:forum/components/CheckoutModal', '959', 'ernestdefoe-kiosk', 'forum/components/CheckoutModal');