import Component from 'flarum/common/Component';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Icon from 'flarum/common/components/Icon';
import { t } from '../../common/t';
import { store } from '../../common/api';
import ProductCard from './ProductCard';
/**
 * "This is for members — here is how to join", for any locked item. Other
 * extensions render it where their item would be:
 *
 *     import LockedNotice from 'ext:ernestdefoe/kiosk/forum/components/LockedNotice';
 *     <LockedNotice type="syllabus-course" id={course.id} name={course.title} />
 *
 * It asks Kiosk which products unlock the item (local rows, one request) and
 * renders nothing at all when none do, so it is safe to drop in anywhere.
 */
export default class LockedNotice extends Component {
  products = null;
  meta = null;
  oninit(vnode) {
    super.oninit(vnode);
    store({
      type: this.attrs.type,
      id: this.attrs.id
    }).then(({
      data,
      meta
    }) => {
      this.products = data;
      this.meta = meta;
      m.redraw();
    }, () => {
      this.products = [];
      m.redraw();
    });
  }
  view() {
    if (this.products === null) return m(LoadingIndicator, {
      display: "block"
    });
    if (!this.products.length || !this.meta) return null;
    return m("section", {
      className: "KioskLocked"
    }, m("h2", {
      className: "KioskLocked-title"
    }, m(Icon, {
      name: "fas fa-lock"
    }), this.attrs.title || (this.attrs.name ? t('forum.locked.title_named', {
      name: this.attrs.name
    }) : t('forum.locked.title'))), m("div", {
      className: "KioskGrid"
    }, this.products.map(product => m(ProductCard, {
      product: product,
      meta: this.meta,
      context: this.attrs.context
    }))));
  }
}
flarum.reg.add('ernestdefoe-kiosk', 'forum/components/LockedNotice', LockedNotice);