import app from 'flarum/common/app';
const url = path => app.forum.attribute('apiUrl') + '/kiosk' + path;
export function call(method, path, body, params) {
  return app.request({
    method,
    url: url(path),
    body: body ? {
      data: body
    } : undefined,
    params
  });
}
export const store = lookup => call('GET', '/store', undefined, lookup);
export const checkout = (priceId, provider, options = {}) => call('POST', '/checkout', {
  priceId,
  provider,
  ...options
});
export const bump = discussionId => call('POST', `/discussions/${discussionId}/bump`);
export const tips = discussionId => call('GET', `/discussions/${discussionId}/tips`);
export const myPurchases = () => call('GET', '/purchases');
export const purchase = number => call('GET', `/purchases/${number}`);
export const confirm = number => call('POST', `/purchases/${number}/confirm`);
export const cancel = number => call('POST', `/purchases/${number}/cancel`);
flarum.reg.add('ernestdefoe-kiosk', 'common/api', { call: call,store: store,checkout: checkout,bump: bump,tips: tips,myPurchases: myPurchases,purchase: purchase,confirm: confirm,cancel: cancel, });